window.MOTIF_CATALOG_CHUNKS[123]={"cards":[{"id":"MEJE-KW-010112","row_version":1,"title":"중단된 문장을 뒤늦게 마치다","original":"Finishing the Interrupted Sentence","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"말하던 도중 사건이 끼어든 인물이 이후 달라진 감정과 목소리로 원래 문장의 나머지를 끝낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010112/index.html"},{"id":"MEJE-KW-010113","row_version":1,"title":"화재 경보로 시선을 돌리다","original":"Fire Alarm Distraction","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 화재 경보를 일부러 울려 주변 사람들을 다른 곳으로 이동시키거나 행사와 감시를 멈추게 하는 사건이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010113/index.html"},{"id":"MEJE-KW-010114","row_version":1,"title":"불과 유황으로 그린 지옥","original":"Fire and Brimstone Hell","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"지하 동굴과 열기, 화염이 가득한 사후 세계를 익숙한 지옥 이미지로 구성해 고통과 공포를 시각화한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-010114/index.html"},{"id":"MEJE-KW-010115","row_version":2,"title":"뜨거운 사람과 차가운 사람 사이의 삼각관계","original":"Fire and Ice Love Triangle","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물을 둘러싼 연애 경쟁에서 두 구애자를 뜨겁고 적극적인 성격과 차갑고 신중한 성격으로 대비시킨다. 불과 얼음의 두 인물의 불과 얼음 이미지가 연애 경쟁의 성격 대비에 쓰인 경우다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010115/index.html"},{"id":"MEJE-KW-010116","row_version":2,"title":"총을 비겁함의 상징으로 보다","original":"Firearms Are Cowardly","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 인물이나 집단이 총을 쓰는 일을 명예롭지 못하고 위험을 피하는 방식으로 평가하는 가치관이다. 그 평가가 무기의 실제 성질을 뜻하지는 않는다. 총기의 등장이 바꾼 시대처럼 총기가 사회를 바꾸는 설정에서는 이를 비겁하다고 보는 인물의 가치관이 갈등이 된다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010116/index.html"},{"id":"MEJE-KW-010117","row_version":1,"title":"총기의 등장이 바꾼 시대","original":"Firearms Are Revolutionary","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"중세풍 사회에 총과 대포가 퍼지며 전쟁 방식과 권력 관계가 바뀌고 기존 전사 계층의 지위가 흔들리는 세계 변화다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-010117/index.html"},{"id":"MEJE-KW-010118","row_version":1,"title":"불꽃으로 변한 눈동자","original":"Fireball Eyeballs","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 눈에 불꽃이 타오르는 듯 그려 분노와 결의, 흥분 또는 초자연적 위협을 한눈에 드러낸다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010118/index.html"},{"id":"MEJE-KW-010119","row_version":1,"title":"던질 수 있는 불덩이","original":"Fireballs","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법이나 초능력으로 불을 공처럼 뭉쳐 원거리 공격으로 내보내는 능력이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-010119/index.html"},{"id":"MEJE-KW-010120","row_version":1,"title":"숨결 공격의 역류","original":"Firebreather Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"상대의 방해로 공격자의 불·에너지 등 숨결 공격이나 충전된 힘이 제대로 발사되지 못하고 자신에게 되돌아오는 전개.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010120/index.html"},{"id":"MEJE-KW-010121","row_version":1,"title":"매운 음식 뒤의 만화적 화염","original":"Fire-Breathing Diner","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 매운 음식을 먹자 얼굴이 붉어지고 입에서 불이 나오는 듯한 과장으로 자극을 표현한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010121/index.html"},{"id":"MEJE-KW-010122","row_version":1,"title":"불을 뿜는 무기","original":"Fire-Breathing Weapon","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작품에 등장하는 화염 분사형 무기로, 가까운 공간의 위험성과 불의 위압감을 전투 장면에 더한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-010122/index.html"},{"id":"MEJE-KW-010123","row_version":1,"title":"학교 관행에 맞선 교사의 해고","original":"Fired Teacher","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"학생과 다른 방식으로 소통하거나 학교의 관행에 맞서는 교사가 해고되고 학생들이 그의 복귀를 바라며 움직이는 이야기다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010123/index.html"},{"id":"MEJE-KW-010124","row_version":3,"title":"불을 지르는 소방관","original":"Firefighter Arsonist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"화재를 막아야 할 소방관이 오히려 방화를 저지른다는 반전으로 직업의 신뢰와 인물의 행동을 충돌시킨다. 소방 활동에 나선 주인공들은 평소 소방과 무관한 주인공이 활동에 참여하는 회차로, 이 카드의 직업적 반전과 대비된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010124/index.html"},{"id":"MEJE-KW-010125","row_version":1,"title":"소방 활동에 나선 주인공들","original":"Firefighting Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평소 소방과 무관한 인물들이 한 회차 동안 소방 활동에 참여하며 낯선 역할 속에서 진지한 위기나 소동을 겪는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010125/index.html"},{"id":"MEJE-KW-010126","row_version":1,"title":"반딧불이가 밝히는 순간","original":"Firefly Scene","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"밤의 반딧불이를 배경으로 인물들이 잠시 멈춰 서서 관계나 마음의 변화를 나누는 장면이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010126/index.html"},{"id":"MEJE-KW-010127","row_version":1,"title":"함께 싸우며 맺어진 우정","original":"Fire-Forged Friends","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 위험한 싸움을 겪은 두 인물이 서로의 능력과 의지를 인정해 우호적이거나 적어도 덜 적대적인 관계가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010127/index.html"},{"id":"MEJE-KW-010128","row_version":1,"title":"소방 호스로 맞서는 장면","original":"Fire Hose Cannon","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 강한 물줄기를 내는 소방 호스를 즉석에서 활용해 위협을 막거나 상대를 밀어내는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010128/index.html"},{"id":"MEJE-KW-010129","row_version":1,"title":"소방서의 달마티안","original":"Firehouse Dalmatian","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"점박이 달마티안이 소방서와 함께 등장해 소방대의 동료나 마스코트처럼 그려지는 동물 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010129/index.html"},{"id":"MEJE-KW-010130","row_version":2,"title":"불과 얼음의 두 인물","original":"Fire/Ice Duo","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"불과 얼음의 힘을 가진 인물 둘이 동료나 적으로 거듭 만나 서로의 강점과 약점을 선명하게 드러내는 관계 구도다. 불·얼음·번개의 기본 공격 삼종이 게임의 공격 속성 묶음이라면, 이 카드는 불과 얼음 힘을 가진 인물 사이의 관계다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010130/index.html"},{"id":"MEJE-KW-010131","row_version":2,"title":"불·얼음·번개의 기본 공격 삼종","original":"Fire, Ice, Lightning","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"게임과 환상 작품이 불, 얼음, 번개를 가장 기본적인 공격 속성의 묶음으로 두어 기술과 적의 상성을 구성한다. 불·물·바람의 세 요소은 불·물·바람을 묶는 다른 원소 구도로, 불·얼음·번개 묶음과 비교할 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-010131/index.html"},{"id":"MEJE-KW-010132","row_version":1,"title":"남성성으로 코드화한 불","original":"Fire Is Masculine","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 불의 힘과 열정, 공격성을 남성적인 인물상과 연결해 성별 이미지를 만드는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010132/index.html"},{"id":"MEJE-KW-010133","row_version":1,"title":"불을 붉게 표시하다","original":"Fire Is Red","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"실제 불꽃의 색과 관계없이 작품의 요소 표시와 의상, 능력 연출에서 불을 붉은색으로 일관되게 구분한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010133/index.html"},{"id":"MEJE-KW-010134","row_version":2,"title":"불로 되살아남을 막다","original":"Fire Keeps It Dead","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"죽은 존재가 다시 살아날 수 있는 세계에서 불에 의한 소멸만이 부활을 막는다고 정한 초자연적 규칙이다. 악을 정화하는 불가 불에 악을 없애는 정화 능력을 부여한다면, 이 세계 규칙은 되살아남을 막는 데 초점을 둔다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010134/index.html"},{"id":"MEJE-KW-010135","row_version":1,"title":"추락자를 받아내는 구조망","original":"Fireman's Safety Net","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"높은 곳에서 떨어지는 인물을 소방대의 구조망이나 탄성 있는 천으로 받아내는 장면에 쓰이는 구조 도구다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-010135/index.html"},{"id":"MEJE-KW-010136","row_version":2,"title":"혼란을 알리는 불길","original":"Fire Means Chaos","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"군중이나 공간이 통제를 잃은 장면에 불길을 함께 배치해 상황의 혼란과 급격한 악화를 시각화한다. 안식의 불빛에서 불은 안식과 동행을 뜻하지만, 여기서는 통제를 잃은 공간을 나타낸다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010136/index.html"},{"id":"MEJE-KW-010137","row_version":1,"title":"매력적인 소방관 이미지","original":"Firemen Are Hot","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 소방관의 구조 활동과 체력을 외모의 매력으로 연결해 관객의 호감을 끌어내는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010137/index.html"},{"id":"MEJE-KW-010138","row_version":3,"title":"안식의 불빛","original":"Fire of Comfort","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"난로나 모닥불의 따뜻한 빛을 휴식과 보호, 함께 머무는 시간의 상징으로 사용한다. 혼란을 알리는 불길의 불길은 혼란을 알리는 이미지로, 편안함을 주는 이 불빛과 다른 정서를 만든다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010138/index.html"},{"id":"MEJE-KW-010139","row_version":1,"title":"악을 정화하는 불","original":"Fire Purifies","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품 세계에서 불이 악한 힘이나 오염된 부분을 없애고 남은 존재를 정화할 수 있다는 초자연적 규칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010139/index.html"},{"id":"MEJE-KW-010140","row_version":1,"title":"신에게서 전해진 금지된 힘과 지식","original":"Fire Stolen from the Gods","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"신격 존재만 지니던 지식이나 힘이 훔쳐지거나 몰래 전해져 필멸자의 손에 들어왔다는 신화적 기원담. 그 대상이 반드시 불일 필요는 없다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010140/index.html"},{"id":"MEJE-KW-010141","row_version":2,"title":"불과 물로 만든 대조","original":"Fire/Water Juxtaposition","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"두 인물이나 장소에 불과 물의 이미지를 각각 붙여 서로 다른 성격과 정서, 가치를 선명하게 대비한다. 불·물·바람의 세 요소의 세 원소 가운데 불과 물을 인물·장면의 대조 이미지로 사용하는 경우다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010141/index.html"},{"id":"MEJE-KW-010142","row_version":1,"title":"불·물·바람의 세 요소","original":"Fire, Water, Wind","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"환상 작품이 흙을 제외하고 불, 물, 바람을 주요 원소 힘의 세 갈래로 묶어 인물과 능력을 배분한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-010142/index.html"},{"id":"MEJE-KW-010143","row_version":1,"title":"작은 장작 꾸러미가 건축 자원이 되다","original":"Firewood Resources","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략게임에서 일꾼이 옮기는 작고 단순한 나무 꾸러미가 거대한 건물의 건축 자원으로 계산되는 화면 표현이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010143/index.html"},{"id":"MEJE-KW-010144","row_version":2,"title":"사랑의 순간에 터지는 불꽃","original":"Fireworks of Love","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"연인의 고백이나 입맞춤에 맞춰 실제 또는 상상 속 불꽃놀이가 펼쳐져 감정의 고조를 시각화한다. 같은 불꽃이라도 승리와 함께 터지는 불꽃에서는 연애의 절정 대신 싸움의 성취를 기념한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010144/index.html"},{"id":"MEJE-KW-010145","row_version":2,"title":"승리와 함께 터지는 불꽃","original":"Fireworks of Victory","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"주인공의 큰 승리 직후 불꽃놀이나 빛의 쇼가 나타나 사건의 성취를 축제처럼 강조한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010145/index.html"},{"id":"MEJE-KW-010146","row_version":2,"title":"해고를 통보받는 날","original":"Firing Day","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"직장인이 해고를 통보받거나 관리자가 그 결정을 전해야 하는 날을 중심 사건으로 삼아 생계·관계·죄책감의 변화를 보여준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010146/index.html"},{"id":"MEJE-KW-010147","row_version":1,"title":"허공에 총을 쏘는 과시","original":"Firing in the Air a Lot","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품에서 인물이 기세와 승리, 위협을 과장하려고 허공에 연달아 총을 쏘는 시각적 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010147/index.html"},{"id":"MEJE-KW-010148","row_version":1,"title":"한 손으로 총을 다루는 연출","original":"Firing One-Handed","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 인물의 멋과 자신감을 강조하려고 총을 한 손으로 쥔 채 발사하는 모습을 자주 보여주는 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010148/index.html"},{"id":"MEJE-KW-010149","row_version":2,"title":"하늘을 덮는 단단한 궁창","original":"Firmament","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"하늘이 세계 위에 얹힌 둥근 지붕이나 천구이며 그 바깥에 다른 영역이 있다는 신화적 우주 구조를 판타지 세계에 적용한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010149/index.html"},{"id":"MEJE-KW-010150","row_version":2,"title":"첫 상처가 알리는 강적","original":"First Blood","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"좀처럼 다치지 않던 인물이 적과 맞서 처음 피를 흘리며 이번 싸움의 위험과 상대의 힘을 실감하는 장면이다. 첫 상처가 강적의 힘을 드러낼 때 당사자의 놀람에 집중한 장면은 처음 입은 상처에 놀라다과 겹친다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010150/index.html"},{"id":"MEJE-KW-010151","row_version":2,"title":"거대 로봇을 신으로 숭배하다","original":"First Church of Mecha","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"사회가 거대한 전투 로봇을 단순한 기계 이상으로 보고 신격이나 종교의 대상으로 모시는 세계관 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010151/index.html"},{"id":"MEJE-KW-010152","row_version":6,"title":"외계 문명과의 첫 만남","original":"First Contact","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"서로 존재조차 모르던 문명들이 처음 접촉하면서 언어·의도·협력 가능성을 탐색하는 서사 상황이다. 외계 문명이 외진 곳에 도착하면 최초로 만나는 지구인이 외계인을 처음 마주친 농부일 수 있다. 서로를 처음 대하는 문명이 뜻을 잘못 읽으면 첫 접촉에서 생긴 치명적 오해이 발생한다. 언어를 공유하지 않는 만남에서는 수학으로 지성을 증명하다이 대화의 출발점이 된다. 정부와 연구기관은 외계 문명 첫 접촉 전담팀을 꾸려 낯선 문명과의 만남을 준비하기도 한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010152/index.html"},{"id":"MEJE-KW-010153","row_version":1,"title":"외계인을 처음 마주친 농부","original":"First-Contact Farmer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"도시가 아닌 외딴 농촌에 착륙한 외계인이 우연히 그곳의 농부와 먼저 만나 지구인에 대한 첫인상을 얻게 되는 인물 구도다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010153/index.html"},{"id":"MEJE-KW-010154","row_version":3,"title":"첫 접촉에서 생긴 치명적 오해","original":"First Contact Faux Pas","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"처음 만난 문명들이 서로의 언어와 몸짓을 잘못 해석해 적의가 없던 상황도 충돌로 번지는 갈등이다. 수학으로 지성을 증명하다처럼 뜻이 비교적 분명한 신호를 주고받으면 첫 만남의 오해를 줄일 수 있다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-010154/index.html"},{"id":"MEJE-KW-010155","row_version":1,"title":"수학으로 지성을 증명하다","original":"First-Contact Math","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"낯선 외계 존재와 말이 통하지 않을 때 수열이나 수학적 규칙을 주고받아 서로 지성이 있음을 확인하는 소통 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010155/index.html"},{"id":"MEJE-KW-010156","row_version":2,"title":"외계 문명 첫 접촉 전담팀","original":"First Contact Team","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"외계 신호나 유물을 발견한 뒤 과학자·언어 연구자 등 여러 전문가를 모아 첫 교류를 준비하는 공식 조직이다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-010156/index.html"},{"id":"MEJE-KW-010157","row_version":1,"title":"첫 출근날 터진 대형 사건","original":"First Day from Hell","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"새 직장에서 적응할 틈도 없이 재난이나 범죄 같은 위기를 맞아 신입이 곧바로 책임을 떠안는 이야기 시작이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010157/index.html"},{"id":"MEJE-KW-010158","row_version":1,"title":"등교 첫날을 그린 회차","original":"First Day of School Episode","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"새 학교나 첫 학교생활을 시작하는 인물의 긴장과 만남을 한 회차의 중심 사건으로 삼는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010158/index.html"},{"id":"MEJE-KW-010159","row_version":2,"title":"첫 회에 되살아난 인물","original":"First-Episode Resurrection","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이야기가 시작하자마자 죽었던 인물이 부활해 새로운 능력과 관계, 앞으로의 사건을 여는 출발점이 된다. 부활의 의미를 첫 회 마지막에야 밝히면 첫 회 끝에 드러난 진짜 전제으로 다음 회의 전제를 세울 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010159/index.html"},{"id":"MEJE-KW-010160","row_version":1,"title":"첫 회 끝에 드러난 진짜 전제","original":"First-Episode Twist","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"시리즈의 첫 회가 마지막에 큰 비밀을 공개하고 그 반전이 이후 이야기의 기본 조건이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010160/index.html"},{"id":"MEJE-KW-010161","row_version":1,"title":"새아버지보다 친아버지가 선택되다","original":"First Father Wins","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"이혼·별거한 아버지와 어머니의 새 배우자를 대비시키면서 작품이 친아버지에게 관객의 동정과 자녀의 애착이 돌아가도록 구성하는 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010161/index.html"},{"id":"MEJE-KW-010162","row_version":1,"title":"처음 사귄 친구","original":"First Friend","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"외롭거나 마음을 닫았던 인물이 처음으로 친구를 받아들이며 타인과 가까워지는 법을 배우는 관계다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010162/index.html"},{"id":"MEJE-KW-010163","row_version":2,"title":"처음 만난 연인이 나중에 밝혀지다","original":"First Girl After All","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"연애 이야기에서 처음 만났던 상대의 정체를 숨기거나 다른 인물로 오인하게 하다가 마지막 무렵 진짜 첫 인연을 드러낸다. 숨겨졌던 첫 인연을 드러내는 방식은 처음 등장한 연인이 이어지다을 결말까지 늦춰 확인하게 만든다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010163/index.html"},{"id":"MEJE-KW-010164","row_version":2,"title":"처음 등장한 연인이 이어지다","original":"First Girl Wins","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"연애 이야기에서 주인공 앞에 가장 먼저 소개된 연애 상대가 결국 최종 짝이 되는 서사 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010164/index.html"},{"id":"MEJE-KW-010165","row_version":1,"title":"처음 발견한 흰머리","original":"First Gray Hair","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 머리에 처음 난 흰 가닥을 보고 노화와 남은 삶을 의식하기 시작하는 심리적 계기다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010165/index.html"},{"id":"MEJE-KW-010166","row_version":1,"title":"처음 입은 상처에 놀라다","original":"First Injury Reaction","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"다친 적이 없거나 자신이 무적이라고 믿던 인물이 처음 입은 눈에 띄는 상처를 보고 당혹과 두려움을 드러낸다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010166/index.html"},{"id":"MEJE-KW-010167","row_version":2,"title":"시리즈 첫 작품의 압도적 인지도","original":"First Installment Wins","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"연속 작품의 첫 편이 가장 많은 관객에게 알려져 뒤의 편이 개선되더라도 원작의 명성과 인지도를 넘기 어려운 수용 현상이다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010167/index.html"},{"id":"MEJE-KW-010168","row_version":2,"title":"첫 입맞춤의 긴장","original":"First Kiss","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물의 생애 처음 또는 두 연인이 함께 나누는 첫 입맞춤을 기대와 어색함이 큰 관계의 이정표로 그린다. 첫 입맞춤은 첫사랑을 기억하게 하는 인물의 중요한 경험이 되기도 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010168/index.html"},{"id":"MEJE-KW-010169","row_version":1,"title":"남성에서 여성으로 바뀌면 오래 유지되는 변신","original":"First Law of Gender Bending","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품에서 남성에서 여성으로 바뀌는 변신이 반대 방향보다 더 자주 나타나고, 원래 모습으로 돌아가는 과정도 더 오래 미뤄지는 재현 관습.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010169/index.html"},{"id":"MEJE-KW-010170","row_version":1,"title":"등장 요소가 늘면 서사의 초점이 분산되다","original":"First Law of Metafictional Thermodynamics","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연속 작품에 인물이나 장소를 더하면 이를 소개하는 데 분량이 쓰이고 기존 요소가 화면 밖으로 밀리는 경향을 물리 법칙처럼 빗댄 메타 관찰이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010170/index.html"},{"id":"MEJE-KW-010171","row_version":1,"title":"작가가 원하면 돌아오는 죽은 인물","original":"First Law of Resurrection","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"오래 이어지는 작품에서 창작진이 중요 인물을 다시 쓰기로 결정하면 확정적 죽음에도 부활할 방법이 생긴다는 제작 관습이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010171/index.html"},{"id":"MEJE-KW-010172","row_version":1,"title":"긴장이 높아질수록 줄어드는 웃음","original":"First Law of Tragicomedies","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"희극과 비극이 섞인 이야기에서 갈등의 긴장이 커질 때 심각한 장면이 많아지고 웃음은 줄어드는 톤의 배분 경향이다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-010172/index.html"},{"id":"MEJE-KW-010174","row_version":2,"title":"이름을 부르며 가까워지다","original":"First-Name Basis","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"성이나 직함 대신 이름으로 부르기 시작하는 변화로 두 인물의 친밀함과 관계의 새 단계를 드러낸다. 이름을 친밀하게 부르는 변화와 달리 본명 한마디에 담긴 꾸중은 본명으로 상대를 제지한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010174/index.html"},{"id":"MEJE-KW-010175","row_version":1,"title":"본명 한마디에 담긴 꾸중","original":"First-Name Ultimatum","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"평소 별명으로 부르던 상대의 본명을 단호한 어조로 말해 더 이상의 장난을 멈추라는 뜻을 전하는 반복 대사다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010175/index.html"},{"id":"MEJE-KW-010176","row_version":1,"title":"첫 월경을 모른 채 맞은 공포","original":"First Period Panic","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"월경에 관해 미리 배우지 못한 인물이 첫 출혈을 병이나 부상으로 오인하고 두려워하는 상황이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010176/index.html"},{"id":"MEJE-KW-010177","row_version":2,"title":"죽어가는 인물의 눈으로 본 마지막 장면","original":"First-Person Dying Perspective","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 죽기 직전 보는 모습을 화면 전체에 담아 마지막 시야가 닫히는 듯한 공포와 종결감을 전하는 연출이다. 죽음 직전의 시야를 관객에게 전하는 방식은 화면에 적용한 인물의 눈을 빌린 1인칭 시점이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010177/index.html"},{"id":"MEJE-KW-010178","row_version":3,"title":"몸이 보이지 않는 1인칭 게임 시점","original":"First-Person Ghost","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 화면은 인물의 눈을 대신하지만 아래를 보아도 몸통과 다리가 보이지 않아 카메라만 떠다니는 듯 느껴지는 표현이다. 몸이 보이지 않는 문제는 게임에서 인물의 눈을 빌린 1인칭 시점을 화면으로 구현할 때 생기는 표현상의 한계다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010178/index.html"},{"id":"MEJE-KW-010179","row_version":3,"title":"주인공을 곁에서 전하는 1인칭 화자","original":"First-Person Peripheral Narrator","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"이야기의 핵심 인물은 따로 있지만 그 곁에 있는 사람이 자신의 목소리로 사건을 서술해 주인공의 속마음과 비밀을 일정 부분 남겨 둔다. 주인공의 곁에서 말하는 화자는 인물의 눈을 빌린 1인칭 시점을 사용하되 이야기의 중심에 서 있지는 않다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010179/index.html"},{"id":"MEJE-KW-010180","row_version":1,"title":"인물의 눈을 빌린 1인칭 시점","original":"First-Person Perspective","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"한 인물의 경험 안에서 사건을 서술하거나 화면을 그 인물의 시야로 제한해 관객이 그의 관점에서 세계를 만난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010180/index.html"},{"id":"MEJE-KW-010181","row_version":3,"title":"1인칭 슈팅 게임","original":"First-Person Shooter","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"플레이어가 조작 인물의 눈으로 공간을 보며 이동과 조준, 사격을 중심으로 진행하는 게임 장르다. 이 게임 장르는 조작 인물의 시야로 세계를 보는 인물의 눈을 빌린 1인칭 시점을 핵심 화면 규칙으로 삼는다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-010181/index.html"},{"id":"MEJE-KW-010182","row_version":1,"title":"속으로 빈정대는 1인칭 화자","original":"First-Person Smartass","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"이야기를 직접 전하는 인물이 사건 설명에 건조한 농담과 비꼬는 속생각을 계속 섞는 서술 목소리다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010182/index.html"},{"id":"MEJE-KW-010183","row_version":2,"title":"사진 촬영으로 진행하는 게임 과제","original":"First-Person Snapshooter","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 속 적이나 사물의 모습을 카메라에 담는 행동이 임무 완료나 정보 수집의 조건이 되는 상호작용 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010183/index.html"},{"id":"MEJE-KW-010184","row_version":2,"title":"첫 반려동물을 맞는 이야기","original":"First Pet Story","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"반려동물을 처음 기르는 인물이 즐거움과 함께 돌봄의 책임과 예상 밖의 문제를 배워 가는 서사다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010184/index.html"},{"id":"MEJE-KW-010185","row_version":2,"title":"첫 차례의 유리함을 줄이는 규칙","original":"First-Player Advantage Mitigation","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"차례가 있는 게임에서 먼저 행동하는 사람이 얻는 이점을 낮추려고 후공에게 자원을 주거나 선공의 선택을 제한한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010185/index.html"},{"id":"MEJE-KW-010186","row_version":1,"title":"감옥에서 강함을 증명하려는 첫 행동","original":"First Rule of the Yard","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 새 수감자를 위험한 집단에 넣은 뒤 첫 상대에게 힘을 보이지 않으면 곧 피해자가 된다는 관습처럼 그리는 장면이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010186/index.html"},{"id":"MEJE-KW-010187","row_version":1,"title":"방송망 밖에서 처음 판매되는 프로그램","original":"First-Run Syndication","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"제작사가 프로그램을 대형 방송사 편성망에 먼저 싣지 않고 지역 방송국과 독립 방송국에 직접 공급하는 최초 배급 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010187/index.html"},{"id":"MEJE-KW-010188","row_version":2,"title":"처음 보는 눈","original":"First Snow","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"눈을 처음 만난 인물이 하얗게 바뀐 세상에 놀라거나 기뻐하며 낯선 자연을 경험하는 장면이다. 자연을 처음 접하는 놀라움은 처음 마주한 바깥 자연에서 햇빛과 푸른 풍경을 처음 볼 때도 나타난다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010188/index.html"},{"id":"MEJE-KW-010189","row_version":1,"title":"첫 단계에 매달려 목표를 잊다","original":"First-Step Fixation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"더 쉬운 해결책이 생겨도 인물이 원래 계획의 첫 단계만 고집해 결국 달성하려던 목표를 놓치는 희극 상황이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010189/index.html"},{"id":"MEJE-KW-010190","row_version":3,"title":"처음 느끼거나 되찾은 감각","original":"First Time Feeling","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 선천적으로 느껴 본 적 없거나 오랫동안 잃었던 감각·감정을 처음 경험하거나 되찾아 기쁨과 충격을 새롭게 겪는다. 처음 경험한 감각이 통증이라면 처음 입은 상처에 놀라다의 당혹감과 겹친다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010190/index.html"},{"id":"MEJE-KW-010191","row_version":1,"title":"처음 마주한 바깥 자연","original":"First Time in the Sun","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"폐쇄적이거나 황폐한 공간에서 자란 인물이 햇빛·달빛·자연 풍경 등 낯선 바깥세계를 처음 보고 희망이나 경이로움을 느끼는 장면.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010191/index.html"},{"id":"MEJE-KW-010192","row_version":1,"title":"모험이 시작되는 첫 마을","original":"First Town","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"역할놀이게임의 초반에 오래 머물며 사람을 만나고 규칙을 익히는 첫 중심 거점이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010192/index.html"},{"id":"MEJE-KW-010193","row_version":1,"title":"풍족한 환경에서의 사소한 걱정","original":"First-World Problems","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 안정된 생활을 누리는 인물의 작은 불편을 심각한 문제처럼 다루어 더 절박한 곤란과의 격차를 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010193/index.html"},{"id":"MEJE-KW-010194","row_version":1,"title":"어항처럼 둥근 헬멧","original":"Fishbowl Helmet","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"우주나 물속에서 쓰는 장비를 큰 투명 구체가 머리를 감싸는 모습으로 그려 착용자의 얼굴을 잘 보이게 한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-010194/index.html"},{"id":"MEJE-KW-010195","row_version":2,"title":"통치자의 상태를 비추는 땅","original":"Fisher King","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"왕이나 지배자의 건강과 도덕성, 감정이 나라의 날씨와 풍요, 황폐함에 직접 드러나는 세계관 법칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010195/index.html"},{"id":"MEJE-KW-010196","row_version":1,"title":"어안렌즈로 휘어진 화면","original":"Fish-Eye Lens","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"넓은 시야를 둥글게 휘어 보이게 하는 렌즈 효과로 낯섦과 속도감, 어지러운 감각을 만드는 촬영 방식이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010196/index.html"},{"id":"MEJE-KW-010197","row_version":1,"title":"양옆으로 벌어진 멍한 눈","original":"Fish Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"눈동자가 바깥쪽을 향한 모습을 무지함이나 멍함의 표정으로 그리는 시각적 고정관념이다. 실제 눈 정렬 상태가 지능이나 성격을 뜻하지는 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010197/index.html"},{"id":"MEJE-KW-010198","row_version":2,"title":"낚시를 떠나는 특별 회차","original":"Fishing Episode","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연속 작품의 인물들이 함께 낚시를 하며 평소와 다른 장소에서 가족·동료 관계를 다지거나 뜻밖의 사건을 겪는 회차다. 낚시가 연속 작품의 한 회차가 아니라 게임의 별도 활동으로 구현되면 게임 속 낚시 미니게임이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010198/index.html"},{"id":"MEJE-KW-010199","row_version":1,"title":"적을 조금씩 끌어내어 상대하다","original":"Fishing for Mooks","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 한꺼번에 모인 적에게 다가가지 않고 일부만 반응하게 하여 전투를 차례로 처리하는 플레이 방식이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010199/index.html"},{"id":"MEJE-KW-010200","row_version":2,"title":"낚싯바늘에 걸린 낡은 장화","original":"Fishing for Sole","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"물고기를 낚았다고 기대한 인물이 장화나 잡동사니를 건져 올려 허탈한 웃음을 만드는 장면이다. 낚시 중 물고기 대신 장화를 건지는 농담은 낚시를 떠나는 특별 회차의 한 장면으로 쓰인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010200/index.html"},{"id":"MEJE-KW-010201","row_version":1,"title":"게임 속 낚시 미니게임","original":"Fishing Minigame","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"본래 목표와 별도로 낚싯대를 조작하고 물고기를 모으는 작은 게임을 작품 안에 넣어 휴식이나 보상을 제공한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010201/index.html"},{"id":"MEJE-KW-010202","row_version":2,"title":"다른 시대에 놓인 낯선 사람","original":"Fish out of Temporal Water","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"시간 여행이나 긴 잠에서 깨어남 등으로 자신의 시대를 벗어난 인물이 새로운 관습과 기술에 적응해야 하는 인물 상황이다. 낯선 환경이 먼 과거나 미래라면 낯선 환경에 떨어진 인물의 시간적 변형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010202/index.html"},{"id":"MEJE-KW-010203","row_version":1,"title":"낯선 환경에 떨어진 인물","original":"Fish Out of Water","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"익숙하지 않은 문화나 장소, 규칙 속으로 들어간 인물이 당황과 적응을 거치며 갈등과 웃음을 만드는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010203/index.html"},{"id":"MEJE-KW-010204","row_version":1,"title":"물고기를 닮은 사람 종족","original":"Fish People","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"두 팔과 두 다리를 갖췄지만 얼굴과 피부, 호흡 기관이 물고기와 닮은 지능적 수중 종족이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010204/index.html"},{"id":"MEJE-KW-010205","row_version":1,"title":"패배 화면 뒤에 이어지는 게임","original":"Fission Mailed","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 실패나 종료를 알리는 화면을 보여주지만 곧 이야기나 플레이가 이어져 패배 판단이 일부러 틀렸음을 드러낸다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010205/index.html"},{"id":"MEJE-KW-010206","row_version":2,"title":"말다툼을 주먹다짐으로 바꾼 한마디","original":"Fisticuff-Provoking Comment","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"이미 격해진 언쟁에서 한 인물이 결정적인 모욕을 던져 상대가 물리적으로 맞서게 되는 전환점이다. 모욕을 들은 인물이 다시 싸우기로 결심할 때 분노로 다시 움켜쥔 주먹으로 감정을 시각화할 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010206/index.html"},{"id":"MEJE-KW-010207","row_version":1,"title":"맨손 싸움만 허용하는 보스","original":"Fisticuffs Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 보스 대결에서 평소 쓰던 무기가 막히거나 사라져 기본적인 근접 공격만으로 승부해야 한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010207/index.html"},{"id":"MEJE-KW-010208","row_version":2,"title":"분노로 다시 움켜쥔 주먹","original":"Fist of Rage","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"포기하거나 물러서 있던 인물이 사건을 계기로 손을 천천히 움켜쥐며 싸울 결심이 돌아왔음을 보여주는 화면이다. 분노로 손을 움켜쥐는 모습과 결의를 담아 들어 올린 주먹은 비슷한 손동작으로 다른 감정의 방향을 전한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010208/index.html"},{"id":"MEJE-KW-010209","row_version":1,"title":"결의를 담아 들어 올린 주먹","original":"Fist Pump","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 어깨 높이나 머리 위로 주먹을 들어 목표를 이루겠다는 의지나 성취의 기쁨을 표시하는 몸짓이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010209/index.html"},{"id":"MEJE-KW-010210","row_version":1,"title":"운동에 과하게 몰두한 인물","original":"Fitness Nut","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"건강과 체력 단련이 삶의 중심이 되어 일상에서도 운동할 기회를 놓치지 않는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010210/index.html"},{"id":"MEJE-KW-010211","row_version":3,"title":"대놓고 부정행위를 하는 게임 참가자","original":"Five-Aces Cheater","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"정상 규칙으로는 불가능한 패나 결과를 보여 누구나 속임수를 알아볼 수 있는데도 태연하게 승부를 이어가는 희극 장면이다. 도박의 결과를 조작하는 승부를 미리 유리하게 조작하다이 다른 참가자에게도 뻔히 보이면 이 희극 장면과 겹친다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010211/index.html"},{"id":"MEJE-KW-010212","row_version":1,"title":"다섯 회에 걸친 시리즈 도입부","original":"Five-Episode Pilot","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"새 연속 작품이 다섯 회 분량의 긴 첫 이야기를 먼저 내어 세계와 주요 목표를 세우는 편성 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010212/index.html"}]}.cards;